import fs from 'node:fs';
import path from 'node:path';
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { buildLegacyComponents, buildUnifiedComponents, findProjectRoot, HSPROJECT_FILE, isLegacyPlatformVersion, loadProjectConfig, } from '../../bin/configDiscovery.js';
vi.mock('node:fs');
const mockTranslateResult = {
    intermediateRepresentation: {
        intermediateNodesIndexedByUid: { 'app-uid': { componentType: 'app' } },
        profileData: { theme: 'dark' },
    },
    skippedHsMetaFiles: [],
};
vi.mock('@hubspot/project-parsing-lib/translate', () => ({
    translateForLocalDev: vi.fn(),
}));
const mockExistsSync = vi.mocked(fs.existsSync);
const mockReadFileSync = vi.mocked(fs.readFileSync);
const mockReaddirSync = vi.mocked(fs.readdirSync);
describe('isLegacyPlatformVersion', () => {
    it('returns true for undefined', () => {
        expect(isLegacyPlatformVersion(undefined)).toBe(true);
    });
    it('returns true for 2023.2', () => {
        expect(isLegacyPlatformVersion('2023.2')).toBe(true);
    });
    it('returns true for 2025.1', () => {
        expect(isLegacyPlatformVersion('2025.1')).toBe(true);
    });
    it('returns false for 2025.2', () => {
        expect(isLegacyPlatformVersion('2025.2')).toBe(false);
    });
    it('returns false for 2026.03', () => {
        expect(isLegacyPlatformVersion('2026.03')).toBe(false);
    });
    it('returns false for 2026.03-beta', () => {
        expect(isLegacyPlatformVersion('2026.03-beta')).toBe(false);
    });
    it('returns false for 2026.09', () => {
        expect(isLegacyPlatformVersion('2026.09')).toBe(false);
    });
    it('returns false for 2026.09-beta', () => {
        expect(isLegacyPlatformVersion('2026.09-beta')).toBe(false);
    });
});
describe('findProjectRoot', () => {
    beforeEach(() => {
        vi.resetAllMocks();
    });
    it('returns the directory containing hsproject.json', () => {
        mockExistsSync.mockImplementation((p) => String(p).endsWith(HSPROJECT_FILE));
        const result = findProjectRoot('/project/src/app');
        expect(result).toBe('/project/src/app');
    });
    it('walks up parent directories until it finds hsproject.json', () => {
        mockExistsSync.mockImplementation((p) => String(p) === `/project/${HSPROJECT_FILE}`);
        const result = findProjectRoot('/project/src/app');
        expect(result).toBe('/project');
    });
    it('throws when hsproject.json is not found in any parent', () => {
        mockExistsSync.mockReturnValue(false);
        expect(() => findProjectRoot('/project/src')).toThrow(HSPROJECT_FILE);
    });
});
describe('loadProjectConfig', () => {
    beforeEach(() => {
        vi.resetAllMocks();
    });
    it('reads and parses hsproject.json', () => {
        mockReadFileSync.mockReturnValue(JSON.stringify({
            name: 'my-app',
            srcDir: 'src',
            platformVersion: '2026.03',
        }));
        const config = loadProjectConfig('/project');
        expect(config).toEqual({
            name: 'my-app',
            srcDir: 'src',
            platformVersion: '2026.03',
        });
        expect(mockReadFileSync).toHaveBeenCalledWith(path.join('/project', HSPROJECT_FILE));
    });
});
describe('buildLegacyComponents', () => {
    const projectDir = '/project';
    const projectConfig = { name: 'my-app', srcDir: 'src' };
    beforeEach(() => {
        vi.resetAllMocks();
    });
    it('discovers public-app.json in subdirectories', () => {
        mockExistsSync.mockImplementation((p) => {
            const str = String(p);
            return (str === '/project/src' || str === '/project/src/myapp/public-app.json');
        });
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        mockReaddirSync.mockReturnValue([
            { name: 'myapp', isDirectory: () => true },
        ]);
        mockReadFileSync.mockReturnValue(JSON.stringify({
            name: 'My App',
            uid: 'myapp',
            extensions: { crm: { cards: [] } },
        }));
        const components = buildLegacyComponents(projectDir, projectConfig);
        expect(components).toHaveProperty('myapp');
        expect(components['myapp'].type).toBe('public-app');
        expect(components['myapp'].path).toBe('/project/src/myapp');
    });
    it('discovers app.json as a private app', () => {
        mockExistsSync.mockImplementation((p) => {
            const str = String(p);
            return str === '/project/src' || str === '/project/src/myapp/app.json';
        });
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        mockReaddirSync.mockReturnValue([
            { name: 'myapp', isDirectory: () => true },
        ]);
        mockReadFileSync.mockReturnValue(JSON.stringify({
            name: 'My App',
            scopes: [],
            extensions: { crm: { cards: [] } },
        }));
        const components = buildLegacyComponents(projectDir, projectConfig);
        expect(components['myapp'].type).toBe('private-app');
    });
    it('prefers public-app.json over app.json when both are present', () => {
        mockExistsSync.mockImplementation((p) => {
            const str = String(p);
            return (str === '/project/src' ||
                str === '/project/src/myapp/public-app.json' ||
                str === '/project/src/myapp/app.json');
        });
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        mockReaddirSync.mockReturnValue([
            { name: 'myapp', isDirectory: () => true },
        ]);
        mockReadFileSync.mockReturnValue(JSON.stringify({
            name: 'My App',
            uid: 'myapp',
            extensions: { crm: { cards: [] } },
        }));
        const components = buildLegacyComponents(projectDir, projectConfig);
        expect(components['myapp'].type).toBe('public-app');
    });
    it('throws when source directory does not exist', () => {
        mockExistsSync.mockReturnValue(false);
        expect(() => buildLegacyComponents(projectDir, projectConfig)).toThrow('Source directory not found');
    });
    it('throws when no app configurations are found', () => {
        mockExistsSync.mockImplementation((p) => String(p) === '/project/src');
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        mockReaddirSync.mockReturnValue([
            { name: 'assets', isDirectory: () => true },
        ]);
        expect(() => buildLegacyComponents(projectDir, projectConfig)).toThrow('No app configurations');
    });
    it('skips non-directory entries', () => {
        mockExistsSync.mockImplementation((p) => String(p) === '/project/src');
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        mockReaddirSync.mockReturnValue([
            { name: 'README.md', isDirectory: () => false },
        ]);
        expect(() => buildLegacyComponents(projectDir, projectConfig)).toThrow('No app configurations');
    });
});
describe('buildUnifiedComponents', () => {
    const projectDir = '/project';
    const projectConfig = {
        name: 'my-app',
        srcDir: 'src',
        platformVersion: '2026.03',
    };
    beforeEach(async () => {
        vi.resetAllMocks();
        const { translateForLocalDev } = await import('@hubspot/project-parsing-lib/translate');
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        vi.mocked(translateForLocalDev).mockResolvedValue(mockTranslateResult);
    });
    it('calls translateForLocalDev with the correct context', async () => {
        const { translateForLocalDev } = await import('@hubspot/project-parsing-lib/translate');
        await buildUnifiedComponents(projectDir, projectConfig, 12345);
        expect(translateForLocalDev).toHaveBeenCalledWith({
            projectSourceDir: path.resolve(projectDir, projectConfig.srcDir),
            platformVersion: projectConfig.platformVersion,
            accountId: 12345,
        });
    });
    it('returns the component map and profileData from the translation result', async () => {
        const result = await buildUnifiedComponents(projectDir, projectConfig);
        expect(result.components).toEqual({ 'app-uid': { componentType: 'app' } });
        expect(result.profileData).toEqual({ theme: 'dark' });
    });
    it('throws when platformVersion is missing', async () => {
        const configWithoutVersion = { name: 'my-app', srcDir: 'src' };
        await expect(buildUnifiedComponents(projectDir, configWithoutVersion)).rejects.toThrow('platformVersion is required');
    });
});
